#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    vector<int> v = {3, 1, 4, 1, 5};
    int limit = 2;

    auto ok = [&limit](int x) {
        return x > limit;
    };

    limit = {final};

    int n = count_if(v.begin(), v.end(), ok);
    cout << "门槛 " << limit << " 以上有 " << n << " 个" << endl;
    return 0;
}
